private fun reviewedRobinhoodCompanyLogo(stock: Stock): ReviewedRobinhoodCompanyLogo? {
    val reviewed = robinhoodCompanyLogos[stock.symbol] ?: return null
    if (stock.id.value != "robinhood:${reviewed.assetId}") return null
    val deployment = stock.deployments.singleOrNull() ?: return null
    if (deployment.chainId != "4663" || !deployment.address.equals(reviewed.contract, ignoreCase = true)) return null
    return reviewed
}

internal fun robinhoodCompanyLogoFallback(stock: Stock): String? = reviewedRobinhoodCompanyLogo(stock)?.url

internal fun robinhoodCompanyLogoNeedsDarkBackground(stock: Stock): Boolean =
    reviewedRobinhoodCompanyLogo(stock)?.darkBackground == true
